#define MAX_LEN 101
#define LIMIT 1024

char expr[MAX_LEN];
int unknowns_pos[5];
int unknown_count;
int n;
int max_result;
int found_valid;

char symbols[] = "01+-*()";
int sym_count = 7;

int evaluate(const char *s, int len);
int parse_expr(const char *s, int *pos, int len, int *res);
int parse_term(const char *s, int *pos, int len, int *res);
int parse_factor(const char *s, int *pos, int len, int *res);
int parse_number(const char *s, int *pos, int len, int *res);

int in_range(int val) {
    return val >= 0 && val < LIMIT;
}

int parse_number(const char *s, int *pos, int len, int *res) {
    if (*pos >= len) return 0;
    if (!isdigit(s[*pos])) return 0;
    int val = 0;
    while (*pos < len && isdigit(s[*pos])) {
        val = val * 2 + (s[*pos] - '0');
        if (!in_range(val)) return 0;
        (*pos)++;
    }
    *res = val;
    return 1;
}

int parse_factor(const char *s, int *pos, int len, int *res) {
    if (*pos >= len) return 0;
    if (s[*pos] == '(') {
        (*pos)++;
        int val;
        if (!parse_expr(s, pos, len, &val)) return 0;
        if (*pos >= len || s[*pos] != ')') return 0;
        (*pos)++;
        *res = val;
        return 1;
    }
    return parse_number(s, pos, len, res);
}

int parse_term(const char *s, int *pos, int len, int *res) {
    if (!parse_factor(s, pos, len, res)) return 0;
    while (*pos < len && s[*pos] == '*') {
        (*pos)++;
        int rhs;
        if (!parse_factor(s, pos, len, &rhs)) return 0;
        int val = (*res) * rhs;
        if (!in_range(val)) return 0;
        *res = val;
    }
    return 1;
}

int parse_expr(const char *s, int *pos, int len, int *res) {
    if (!parse_term(s, pos, len, res)) return 0;
    while (*pos < len && (s[*pos] == '+' || s[*pos] == '-')) {
        char op = s[*pos];
        (*pos)++;
        int rhs;
        if (!parse_term(s, pos, len, &rhs)) return 0;
        int val;
        if (op == '+') {
            val = *res + rhs;
        } else {
            val = *res - rhs;
        }
        if (!in_range(val)) return 0;
        *res = val;
    }
    return 1;
}

int evaluate(const char *s, int len) {
    int pos = 0;
    int res;
    if (!parse_expr(s, &pos, len, &res)) return -1;
    if (pos != len) return -1;
    return res;
}

int is_valid_expression(const char *s, int len) {
    // check parentheses balance
    int bal = 0;
    for (int i = 0; i < len; i++) {
        if (s[i] == '(') bal++;
        else if (s[i] == ')') bal--;
        if (bal < 0) return 0;
    }
    if (bal != 0) return 0;
    // Check no two operators in a row, no leading operator, no trailing operator
    // Also check operators are between numbers/parens
    int last_was_op_or_open = 1; // start allows number or '('
    for (int i = 0; i < len; i++) {
        char c = s[i];
        if (c == '+' || c == '-' || c == '*') {
            if (last_was_op_or_open) return 0;
            last_was_op_or_open = 1;
        } else if (c == '(') {
            if (!last_was_op_or_open && i > 0 && s[i-1] != '(' && s[i-1] != '+' && s[i-1] != '-' && s[i-1] != '*') return 0;
            last_was_op_or_open = 1;
        } else if (c == ')') {
            if (last_was_op_or_open) return 0;
            last_was_op_or_open = 0;
        } else { // digit
            if (i > 0 && s[i-1] == ')') return 0;
            last_was_op_or_open = 0;
        }
    }
    if (last_was_op_or_open) return 0;
    return 1;
}

void backtrack(int idx) {
    if (idx == unknown_count) {
        // Check if valid expression
        if (!is_valid_expression(expr, n)) return;
        int res = evaluate(expr, n);
        if (res != -1) {
            found_valid = 1;
            if (res > max_result) max_result = res;
        }
        return;
    }
    int pos = unknowns_pos[idx];
    for (int i = 0; i < sym_count; i++) {
        expr[pos] = symbols[i];
        backtrack(idx + 1);
    }
    expr[pos] = '.';
}

int main() {
    fgets(expr, MAX_LEN, stdin);
    n = strlen(expr);
    if (expr[n-1] == '\n') expr[--n] = '\0';

    unknown_count = 0;
    for (int i = 0; i < n; i++) {
        if (expr[i] == '.') {
            unknowns_pos[unknown_count++] = i;
        }
    }

    max_result = -1;
    found_valid = 0;
    backtrack(0);

    if (found_valid) printf("%d\n", max_result);
    else printf("-1\n");

    return 0;
}

