        pos++;
        if (val >= 1024) { valid = 0; return 0; }
    }
    return val;
}

int parse_factor() {
    if (!valid) return 0;
    if (pos < (int)strlen(expr) && expr[pos] == '(') {
        pos++; // consume '('
        int val = parse_expr();
        if (!valid) return 0;
        if (pos >= (int)strlen(expr) || expr[pos] != ')') { valid = 0; return 0; }
        pos++; // consume ')'
        return val;
    } else {
        return parse_number();
    }
}

int parse_term() {
    if (!valid) return 0;
    int val = parse_factor();
    while (valid && pos < (int)strlen(expr) && expr[pos] == '*') {
        pos++;
        int rhs = parse_factor();
        if (!valid) return 0;
        val = val * rhs;
        if (val < 0 || val >= 1024) { valid = 0; return 0; }
    }
    return val;
}

int parse_expr() {
    if (!valid) return 0;
    int val = parse_term();
    while (valid && pos < (int)strlen(expr) && (expr[pos] == '+' || expr[pos] == '-')) {
        char op = expr[pos];
        pos++;
        int rhs = parse_term();
        if (!valid) return 0;
        if (op == '+') val = val + rhs;
        else val = val - rhs;
        if (val < 0 || val >= 1024) { valid = 0; return 0; }
    }
    return val;
}

