#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 105
#define MAXV 1024
#define NEG_INF (-1000000000)

static char s[MAXN];
static int n;

/* dp[l][r][v] = 1 iff substring s[l..r] can be a valid expression with value v */
static unsigned char dp[MAXN][MAXN][MAXV];

/* possible replacement check */
static int can_be_digit_char(char c, char d) {
    return c == d || c == '.';
}
static int can_be_op_char(char c, char op) {
    return c == op || c == '.';
}
static int can_be_char(char c, char x) {
    return c == x || c == '.';
}

/* number validity:
   substring [l..r] must be a binary number without leading zeros except "0",
   and value < 1024.
*/
static int parse_number(int l, int r) {
    int len = r - l + 1;
    if (len <= 0) return -1;
    if (len > 10) return -1; /* any 11-bit positive number >= 1024, and 10+ leading-zero forms invalid except single 0 */
    if (len > 1 && can_be_digit_char(s[l], '0')) {
        /* if first char can be 0, we might still choose 1 if '.', so not immediate invalid */
    }

    int possible[MAXV];
    int i, v;
    memset(possible, 0, sizeof(possible));
    possible[0] = 1;

    for (i = l; i <= r; i++) {
        int next[MAXV];
        memset(next, 0, sizeof(next));
        for (v = 0; v < MAXV; v++) if (possible[v]) {
            if (can_be_digit_char(s[i], '0')) {
                int nv = v * 2;
                if (nv < MAXV) next[nv] = 1;
            }
            if (can_be_digit_char(s[i], '1')) {
                int nv = v * 2 + 1;
                if (nv < MAXV) next[nv] = 1;
            }
        }
        memcpy(possible, next, sizeof(posible));
    }

    /* Need at least one valid assignment and no leading zero unless single digit */
    for (v = MAXV - 1; v >= 0; v--) {
        if (!possible[v]) continue;

        if (len > 1) {
            /* check existence of an assignment producing v with first digit 1 */
            int cur[MAXV], next[MAXV];
            memset(cur, 0, sizeof(cur));
            if (can_be_digit_char(s[l], '1')) cur[1] = 1;
            else continue;
            for (i = l + 1; i <= r; i++) {
                memset(next, 0, sizeof(next));
                int x;
                for (x = 0; x < MAXV; x++) if (cur[x]) {
                    if (can_be_digit_char(s[i], '0')) {
                        int nv = x * 2;
                        if (nv < MAXV) next[nv] = 1;
                    }
                    if (can_be_digit_char(s[i], '1')) {
                        int nv = x * 2 + 1;
                        if (nv < MAXV) next[nv] = 1;
                    }
                }
                memcpy(cur, next, sizeof(cur));
            }
            if (cur[v]) return v;
        } else {
            return v;
        }
    }
    return -1;
}

/* mark all possible numeric values for [l..r] */
static void add_number_values(int l, int r) {
    int len = r - l + 1;
    if (len <= 0 || len > 10) return;

    int cur[MAXV], next[MAXV];
    memset(cur, 0, sizeof(cur));

    if (len == 1) {
        if (can_be_digit_char(s[l], '0')) dp[l][r][0] = 1;
        if (can_be_digit_char(s[l], '1')) dp[l][r][1] = 1;
        return;
    }

    /* multi-digit number must start with 1 */
    if (!can_be_digit_char(s[l], '1')) return;
    cur[1] = 1;

    for (int i = l + 1; i <= r; i++) {
        memset(next, 0, sizeof(next));
        for (int v = 0; v < MAXV; v++) if (cur[v]) {
            if (can_be_digit_char(s[i], '0')) {
                int nv = v * 2;
                if (nv < MAXV) next[nv] = 1;
            }
            if (can_be_digit_char(s[i], '1')) {
                int nv = v * 2 + 1;
                if (nv < MAXV) next[nv] = 1;
            }
        }
        memcpy(cur, next, sizeof(cur));
    }

    for (int v = 0; v < MAXV; v++) if (cur[v]) dp[l][r][v] = 1;
}

int main(void) {
    if (!fgets(s, sizeof(s), stdin)) return 0;
    n = (int)strlen(s);
    while (n > 0 && (s[n-1] == '\n' || s[n-1] == '\r')) s[--n] = '\0';

    memset(dp, 0, sizeof(dp));

    /* base: numbers */
    for (int l = 0; l < n; l++) {
        for (int r = l; r < n && r < l + 10; r++) {
            add_number_values(l, r);
        }
    }

    /* expressions by increasing length */
    for (int len = 1; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;

            /* parenthesized form: (expr op expr) */
            if (len >= 5 && can_be_char(s[l], '(') && can_be_char(s[r], ')')) {
                for (int k = l + 2; k <= r - 2; k++) {
                    if (!(can_be_op_char(s[k], '+') || can_be_op_char(s[k], '-') || can_be_op_char(s[k], '*'))) continue;

                    for (int a = 0; a < MAXV; a++) if (dp[l+1][k-1][a]) {
                        for (int b = 0; b < MAXV; b++) if (dp[k+1][r-1][b]) {
                            int val;
                            if (can_be_op_char(s[k], '+')) {
                                val = a + b;
                                if (0 <= val && val < MAXV) dp[l][r][val] = 1;
                            }
                            if (can_be_op_char(s[k], '-')) {
                                val = a - b;
                                if (0 <= val && val < MAXV) dp[l][r][val] = 1;
                            }
                            if (can_be_op_char(s[k], '*')) {
                                val = a * b;
                                if (0 <= val && val < MAXV) dp[l][r][val] = 1;
                            }
                        }
                    }
                }
            }

            /* unparenthesized expression:
               operators precedence: * before +/-, and +,- left-to-right.
               We can characterize top-level split:
               - if there exists a top-level + or -, the last such operator is the root
               - otherwise, if there exists a top-level *, the last * is the root
               This allows recursive decomposition.
            */
            int depth = 0;
            int last_pm = -1, last_mul = -1;
            for (int i = l; i <= r; i++) {
                char c = s[i];
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (depth == 0 || c == '.') {
                    /* since '.' may be operator/paren/digit, we cannot reliably use depth logic through '.'
                       So for generic wildcard handling, this scan is unsafe.
                       Therefore, instead of structural scan, try every split k and operator, but only if
                       left/right are valid expressions. This may generate parenthesized-looking parses too,
                       but grammar allows expr op expr without surrounding parentheses only according to precedence.
                       To enforce precedence/associativity, we use two auxiliary notions:
                       E = full expression
                       T = product chain
                       F = number or parenthesized binary op
                       However grammar allows parenthesized arbitrary expr-op-expr. We implement precedence grammar:
                       E := T | E + T | E - T
                       T := F | T * F
                       F := number | (E op E?) no, inside parentheses original grammar again with precedence rules too.
                       Simpler approach: separate nonterminals E,T,F.
                    */
                }
            }
        }
    }

    /* Re-implement properly with E/T/F DP */
    static unsigned char dpe[MAXN][MAXN][MAXV];
    static unsigned char dpt[MAXN][MAXN][MAXV];
    static unsigned char dpf[MAXN][MAXN][MAXV];
    memset(dpe, 0, sizeof(dpe));
    memset(dpt, 0, sizeof(dpt));
    memset(dpf, 0, sizeof(dpf));

    /* F: number */
    for (int l = 0; l < n; l++) {
        for (int r = l; r < n && r < l + 10; r++) {
            int len2 = r - l + 1;
            if (len2 == 1) {
                if (can_be_digit_char(s[l], '0')) dpf[l][r][0] = 1;
                if (can_be_digit_char(s[l], '1')) dpf[l][r][1] = 1;
            } else {
                if (!can_be_digit_char(s[l], '1')) continue;
                int cur[MAXV], next[MAXV];
                memset(cur, 0, sizeof(cur));
                cur[1] = 1;
                for (int i = l + 1; i <= r; i++) {
                    memset(next, 0, sizeof(next));
                    for (int v = 0; v < MAXV; v++) if (cur[v]) {
                        if (can_be_digit_char(s[i], '0')) {
                            int nv = v * 2;
                            if (nv < MAXV) next[nv] = 1;
                        }
                        if (can_be_digit_char(s[i], '1')) {
                            int nv = v * 2 + 1;
                            if (nv < MAXV) next[nv] = 1;
                        }
                    }
                    memcpy(cur, next, sizeof(cur));
                }
                for (int v = 0; v < MAXV; v++) if (cur[v]) dpf[l][r][v] = 1;
            }
        }
    }

    for (int len = 1; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;

            /* F := (E op E) */
            if (len >= 5 && can_be_char(s[l], '(') && can_be_char(s[r], ')')) {
                for (int k = l + 2; k <= r - 2; k++) {
                    if (!(can_be_op_char(s[k], '+') || can_be_op_char(s[k], '-') || can_be_op_char(s[k], '*'))) continue;
                    for (int a = 0; a < MAXV; a++) if (dpe[l+1][k-1][a]) {
                        for (int b = 0; b < MAXV; b++) if (dpe[k+1][r-1][b]) {
                            int val;
                            if (can_be_op_char(s[k], '+')) {
                                val = a + b;
                                if (val < MAXV) dpf[l][r][val] = 1;
                            }
                            if (can_be_op_char(s[k], '-')) {
                                val = a - b;
                                if (val >= 0) dpf[l][r][val] = 1;
                            }
                            if (can_be_op_char(s[k], '*')) {
                                val = a * b;
                                if (val < MAXV) dpf[l][r][val] = 1;
                            }
                        }
                    }
                }
            }

            /* T := F | T * F */
            for (int v = 0; v < MAXV; v++) if (dpf[l][r][v]) dpt[l][r][v] = 1;
            for (int k = l + 1; k <= r - 1; k++) {
                if (!can_be_op_char(s[k], '*')) continue;
                for (int a = 0; a < MAXV; a++) if (dpt[l][k-1][a]) {
                    for (int b = 0; b < MAXV; b++) if (dpf[k+1][r][b]) {
                        int val = a * b;
                        if (val < MAXV) dpt[l][r][val] = 1;
                    }
                }
            }

            /* E := T | E + T | E - T */
            for (int v = 0; v < MAXV; v++) if (dpt[l][r][v]) dpe[l][r][v] = 1;
            for (int k = l + 1; k <= r - 1; k++) {
                if (can_be_op_char(s[k], '+')) {
                    for (int a = 0; a < MAXV; a++) if (dpe[l][k-1][a]) {
                        for (int b = 0; b < MAXV; b++) if (dpt[k+1][r][b]) {
                            int val = a + b;
                            if (val < MAXV) dpe[l][r][val] = 1;
                        }
                    }
                }
                if (can_be_op_char(s[k], '-')) {
                    for (int a = 0; a < MAXV; a++) if (dpe[l][k-1][a]) {
                        for (int b = 0; b < MAXV; b++) if (dpt[k+1][r][b]) {
                            int val = a - b;
                            if (val >= 0) dpe[l][r][val] = 1;
                        }
                    }
                }
            }
        }
    }

    for (int v = MAXV - 1; v >= 0; v--) {
        if (dpe[0][n-1][v]) {
            printf("%d\n", v);
            return 0;
        }
    }
    printf("-1\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

struct Seg {
    int l, r;
    vector<char> expr;
};

string s;
int n;
int dp[105][105][2]; // 0 = min, 1 = max
bool computed[105][105][2];

int applyOp(int a, int b, char op) {
    if (op == '+') {
        if (a + b >= (1 << 10) || a + b < 0) return INF;
        return a + b;
    }
    if (op == '-') {
        if (a - b < 0) return INF;
        return a - b;
    }
    if (op == '*') {
        if (a * b >= (1 << 10) || a * b < 0) return INF;
        return a * b;
    }
    return INF;
}

pair<int,int> solve(int l, int r) {
    if (computed[l][r][0]) return {dp[l][r][0], dp[l][r][1]};
    computed[l][r][0] = computed[l][r][1] = true;
    dp[l][r][0] = INF;
    dp[l][r][1] = -INF;

    // check if it's a number
    bool isNum = true;
    int val = 0;
    for (int i = l; i <= r; i++) {
        if (s[i] == '.' || s[i] == '0' || s[i] == '1') continue;
        isNum = false;
        break;
    }
    if (isNum) {
        // try all possibilities for dots
        vector<int> digits;
        int cnt = 0;
        for (int i = l; i <= r; i++) {
            if (s[i] == '.') cnt++;
        }
        int total = 1 << cnt;
        bool any = false;
        for (int mask = 0; mask < total; mask++) {
            int num = 0;
            int idx = 0;
            bool ok = true;
            for (int i = l; i <= r; i++) {
                int bit;
                if (s[i] == '.') {
                    bit = (mask >> idx) & 1;
                    idx++;
                } else {
                    bit = s[i] - '0';
                }
                if (num == 0 && bit == 0 && i < r) {
                    // leading zero? actually in binary, leading zeros are allowed? 
                    // Number is binary, so leading zeros are fine as they just represent the same number.
                    // But to keep within range, we just compute.
                }
                num = (num << 1) | bit;
                if (num >= (1 << 10)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                any = true;
                dp[l][r][0] = min(dp[l][r][0], num);
                dp[l][r][1] = max(dp[l][r][1], num);
            }
        }
        if (!any) {
            dp[l][r][0] = INF;
            dp[l][r][1] = -INF;
        }
        return {dp[l][r][0], dp[l][r][1]};
    }

    // otherwise it must be ( expr op expr )
    if (s[l] != '(' || s[r] != ')') {
        // invalid
        return {dp[l][r][0], dp[l][r][1]};
    }
    // find split point for the top-level operator
    // need to find the operator that is not inside parentheses
    int depth = 0;
    int opPos = -1;
    for (int i = l+1; i < r; i++) {
        if (s[i] == '(') depth++;
        else if (s[i] == ')') depth--;
        else if (depth == 0 && (s[i] == '+' || s[i] == '-' || s[i] == '*')) {
            opPos = i;
            break;
        }
    }
    if (opPos == -1) {
        // invalid
        return {dp[l][r][0], dp[l][r][1]};
    }
    char op = s[opPos];
    // but the op could be '.' so we need to try all three
    vector<char> ops;
    if (op == '.') {
        ops = {'+', '-', '*'};
    } else {
        ops = {op};
    }
    for (char c : ops) {
        auto left = solve(l+1, opPos-1);
        auto right = solve(opPos+1, r-1);
        if (left.first == INF || right.first == INF) continue;
        // multiplication first? No, the grammar says: parentheses first, then multiplication before add/sub, else left to right.
        // But here we have parentheses so we evaluate left and right fully, then apply operator.
        // However the problem says multiplication is done before add/sub within same precedence level? Actually for this grammar, 
        // inside parentheses it's just expr op expr, and we evaluate that expression respecting precedence: multiplication before add/sub, else left to right.
        // Since we are recursively evaluating subexpressions, we need to apply the operator after evaluating both sides.
        // But the subexpressions themselves may contain operators. So we just apply the operator here.
        // This is correct because we are building the parse tree.
        for (int a : {left.first, left.second}) {
            for (int b : {right.first, right.second}) {
                int res = applyOp(a, b, c);
                if (res == INF) continue;
                dp[l][r][0] = min(dp[l][r][0], res);
                dp[l][r][1] = max(dp[l][r][1], res);
            }
        }
    }
    return {dp[l][r][0], dp[l][r][1]};
}

