// Returns value or -2 on error
int parseExpression() {
    int val = parseTerm();
    if (!valid) return 0;
    while (pos < expr.size() && (expr[pos] == '+' || expr[pos] == '-')) {
        char op = expr[pos++];
        int rhs = parseTerm();
        if (!valid) return 0;
        if (op == '+') val = val + rhs;
        else val = val - rhs;
        if (val < 0 || val >= 1024) { valid = false; return 0; }
    }
    return val;
}

int parseTerm() {
    int val = parseFactor();
    if (!valid) return 0;
    while (pos < expr.size() && expr[pos] == '*') {
        pos++;
        int rhs = parseFactor();
        if (!valid) return 0;
        val = val * rhs;
        if (val < 0 || val >= 1024) { valid = false; return 0; }
    }
    return val;
}

int parseFactor() {
    if (pos >= expr.size()) { valid = false; return 0; }
    if (expr[pos] == '(') {
        pos++;
        int val = parseExpression();
        if (!valid) return 0;
        if (pos >= expr.size() || expr[pos] != ')') { valid = false; return 0; }
        pos++;
        return val;
    }
    return parseNumber();
}

int parseNumber() {
    if (pos >= expr.size() || (expr[pos] != '0' && expr[pos] != '1')) { valid = false; return 0; }
    int val = 0;
    while (pos < expr.size() && (expr[pos] == '0' || expr[pos] == '1')) {
        val = val * 2 + (expr[pos] - '0');
        pos++;
        if (val >= 1024) { valid = false; return 0; }
    }
    return val;
}

