#include <bits/stdc++.h>
using namespace std;

static const int LIMIT = 1024; // values must stay in [0, 2^10)
static const int NEG_INF = -1e9;

struct Node {
    // best[l][r][v] = true iff substring [l, r) can be parsed as this nonterminal with value v
    // We'll store as bitset for speed.
    bitset<LIMIT> bs;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    if (!(cin >> s)) return 0;
    int n = (int)s.size();

    auto canBeDigit = [&](char c) {
        return c == '.' || c == '0' || c == '1';
    };
    auto canBeOp = [&](char c, char op) {
        return c == '.' || c == op;
    };
    auto canBeChar = [&](char c, char t) {
        return c == '.' || c == t;
    };

    // num[l][r]: values achievable by substring s[l..r-1] as <number>
    vector<vector<bitset<LIMIT>>> num(n + 1, vector<bitset<LIMIT>>(n + 1));
    // expr[l][r]: values achievable by substring s[l..r-1] as <expression>
    vector<vector<bitset<LIMIT>>> expr(n + 1, vector<bitset<LIMIT>>(n + 1));

    // Parse numbers
    for (int l = 0; l < n; ++l) {
        if (!canBeDigit(s[l])) continue;
        bitset<LIMIT> cur;
        if (s[l] == '0' || s[l] == '.') cur.set(0);
        if (s[l] == '1' || s[l] == '.') cur.set(1);
        num[l][l + 1] = cur;
        expr[l][l + 1] |= cur; // <expression> ::= <number>

        for (int r = l + 1; r < n; ++r) {
            if (!canBeDigit(s[r])) break;
            bitset<LIMIT> nxt;
            for (int v = 0; v < LIMIT; ++v) {
                if (!cur.test(v)) continue;
                if ((s[r] == '0' || s[r] == '.') && v * 2 < LIMIT) nxt.set(v * 2);
                if ((s[r] == '1' || s[r] == '.') && v * 2 + 1 < LIMIT) nxt.set(v * 2 + 1);
            }
            if (nxt.none()) break;
            num[l][r + 1] = nxt;
            expr[l][r + 1] |= nxt;
            cur = nxt;
        }
    }

    // Helper to combine two value sets with an operation
    auto combine = [&](const bitset<LIMIT>& A, const bitset<LIMIT>& B, char op) {
        bitset<LIMIT> R;
        vector<int> va, vb;
        va.reserve(LIMIT);
        vb.reserve(LIMIT);
        for (int i = 0; i < LIMIT; ++i) if (A.test(i)) va.push_back(i);
        for (int i = 0; i < LIMIT; ++i) if (B.test(i)) vb.push_back(i);

        if (op == '+') {
            for (int a : va) {
                for (int b : vb) {
                    int c = a + b;
                    if (c < LIMIT) R.set(c);
                }
            }
        } else if (op == '-') {
            for (int a : va) {
                for (int b : vb) {
                    int c = a - b;
                    if (0 <= c && c < LIMIT) R.set(c);
                }
            }
        } else { // '*'
            for (int a : va) {
                if (a == 0) {
                    if (!vb.empty()) R.set(0);
                    continue;
                }
                for (int b : vb) {
                    long long c = 1LL * a * b;
                    if (c < LIMIT) R.set((int)c);
                }
            }
        }
        return R;
    };

    // DP by length for expressions
    for (int len = 1; len <= n; ++len) {
        for (int l = 0; l + len <= n; ++l) {
            int r = l + len;

            // Parenthesized: (expr op expr)
            if (len >= 5 && canBeChar(s[l], '(') && canBeChar(s[r - 1], ')')) {
                for (int m = l + 2; m <= r - 2; ++m) { // operator position
                    char realOp;
                    bool anyOp = false;
                    for (char op : {'+', '-', '*'}) {
                        if (!canBeOp(s[m], op)) continue;
                        anyOp = true;
                        realOp = op;
                        (void)realOp;
                        const auto &L = expr[l + 1][m];
                        const auto &R = expr[m + 1][r - 1];
                        if (L.none() || R.none()) continue;
                        expr[l][r] |= combine(L, R, op);
                    }
                    if (!anyOp) continue;
                }
            }

            // Non-parenthesized expression:
            // precedence: * before +/-, and +,- left-to-right.
            //
            // Grammar equivalent:
            // expr := term ((+|-) term)*
            // term := factor ('*' factor)*
            // factor := number | '(' expr op expr ')'
            //
            // But parenthesized binary expression is already included in expr[].
            // We need a DP respecting this precedence/associativity on the substring.
        }
    }

    // To handle precedence and left-to-right properly, use additional DPs:
    // term[l][r]: products of factors, left associative (for * associative anyway)
    // factor == expr atom: number or parenthesized binary expression only
    vector<vector<bitset<LIMIT>>> factor(n + 1, vector<bitset<LIMIT>>(n + 1));
    vector<vector<bitset<LIMIT>>> term(n + 1, vector<bitset<LIMIT>>(n + 1));
    vector<vector<bitset<LIMIT>>> full(n + 1, vector<bitset<LIMIT>>(n + 1));

    // factor = number initially
    for (int l = 0; l <= n; ++l)
        for (int r = 0; r <= n; ++r)
            factor[l][r] = num[l][r];

    // Build parenthesized factors/expressions and then terms/full expressions by length
    for (int len = 1; len <= n; ++len) {
        for (int l = 0; l + len <= n; ++l) {
            int r = l + len;

            // First, parenthesized binary expression as factor
            if (len >= 5 && canBeChar(s[l], '(') && canBeChar(s[r - 1], ')')) {
                for (int m = l + 2; m <= r - 2; ++m) {
                    for (char op : {'+', '-', '*'}) {
                        if (!canBeOp(s[m], op)) continue;
                        const auto &L = full[l + 1][m];
                        const auto &R = full[m + 1][r - 1];
                        if (L.none() || R.none()) continue;
                        factor[l][r] |= combine(L, R, op);
                    }
                }
            }

            // term := factor | term * factor   (left associative, but multiplication associative for valid values)
            term[l][r] |= factor[l][r];
            for (int m = l + 1; m < r - 1; ++m) {
                if (!canBeOp(s[m], '*')) continue;
                const auto &L = term[l][m];
                const auto &R = factor[m + 1][r];
                if (L.none() || R.none()) continue;
                term[l][r] |= combine(L, R, '*');
            }

            // full := term | full (+|-) term   left associative
            full[l][r] |= term[l][r];
            for (int m = l + 1; m < r - 1; ++m) {
                if (canBeOp(s[m], '+')) {
                    const auto &L = full[l][m];
                    const auto &R = term[m + 1][r];
                    if (!L.none() && !R.none()) full[l][r] |= combine(L, R, '+');
                }
                if (canBeOp(s[m], '-')) {
                    const auto &L = full[l][m];
                    const auto &R = term[m + 1][r];
                    if (!L.none() && !R.none()) full[l][r] |= combine(L, R, '-');
                }
            }
        }
    }

    int ans = -1;
    for (int v = LIMIT - 1; v >= 0; --v) {
        if (full[0][n].test(v)) {
            ans = v;
            break;
        }
    }
    cout << ans << '\n';
    return 0;
}

import java.util.*;

public class Main {
    static final int MAX_VAL = 1023;
    static final char[] CHARS = {'0', '1', '+', '-', '*', '(', ')'};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String expr = sc.nextLine().trim();
        sc.close();

        List<Integer> dotPositions = new ArrayList<>();
        for (int i = 0; i < expr.length(); i++) {
            if (expr.charAt(i) == '.') dotPositions.add(i);
        }

        int k = dotPositions.size();
        if (k > 5) {
            System.out.println(-1);
            return;
        }

        long maxResult = -1;
        char[] base = expr.toCharArray();

        int total = (int) Math.pow(7, k);
        for (int mask = 0; mask < total; mask++) {
            int tmp = mask;
            for (int i = 0; i < k; i++) {
                base[dotPositions.get(i)] = CHARS[tmp % 7];
                tmp /= 7;
            }
            String candidate = new String(base);
            if (isValidExpression(candidate)) {
                Long val = evaluate(candidate);
                if (val != null && val >= 0) {
                    if (val > maxResult) maxResult = val;
                }
            }
        }

        System.out.println(maxResult);
    }

    static boolean isValidExpression(String s) {
        // Grammar check using stack for parentheses and token validity
        // We'll just rely on evaluation catching errors, but do basic check
        if (s.isEmpty()) return false;
        int balance = 0;
        char prev = 0;
        boolean expectNumber = true;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if (!expectNumber) return false;
                balance++;
                prev = c;
                // after '(' we expect number or '('
            } else if (c == ')') {
                if (balance == 0 || expectNumber) return false;
                balance--;
                prev = c;
                expectNumber = false;
            } else if (c == '+' || c == '-' || c == '*') {
                if (expectNumber) return false;
                expectNumber = true;
                prev = c;
            } else if (c == '0' || c == '1') {
                if (!expectNumber) return false;
                expectNumber = false;
                prev = c;
            } else {
                return false;
            }
        }
        if (balance != 0) return false;
        return !expectNumber;
    }

    static Long evaluate(String s) {
        // Convert to postfix and evaluate
        String postfix = infixToPostfix(s);
        if (postfix == null) return null;
        return evalPostfix(postfix);
    }

    static int precedence(char op) {
        if (op == '*' ) return 2;
        if (op == '+' || op == '-') return 1;
        return 0;
    }

    static String infixToPostfix(String s) {
        StringBuilder post = new StringBuilder();
        Stack<Character> ops = new Stack<>();
        boolean lastWasNum = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '0' || c == '1') {
                post.append(c);
                lastWasNum = true;
            } else if (c == '(') {
                ops.push(c);
                lastWasNum = false;
            } else if (c == ')') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    post.append(ops.pop());
                }
                if (ops.isEmpty() || ops.pop() != '(') return null; // mismatched
                lastWasNum = true;
            } else { // operator
                if (!lastWasNum) return null;
                while (!ops.isEmpty() && ops.peek() != '(' && precedence(ops.peek()) >= precedence(c)) {
                    post.append(ops.pop());
                }
                ops.push(c);
                lastWasNum = false;
            }
        }
        while (!ops.isEmpty()) {
            char op = ops.pop();
            if (op == '(') return null;
            post.append(op);
        }
        return post.toString();
    }

    static Long evalPostfix(String post) {
        Stack<Integer> stack = new Stack<>();
        for (int i = 0; i < post.length(); i++) {
            char c = post.charAt(i);
            if (c == '0' || c == '1') {
                // read full number
                int j = i;
                while (j < post.length() && (post.charAt(j) == '0' || post.charAt(j) == '1')) j++;
                String numStr = post.substring(i, j);
                int num = Integer.parseInt(numStr, 2);
                if (num > MAX_VAL) return null;
                stack.push(num);
                i = j - 1;
            } else {
                if (stack.size() < 2) return null;
                int b = stack.pop();
                int a = stack.pop();
                int res;
                if (c == '+') {
                    res = a + b;
                } else if (c == '-') {
                    res = a - b;
                } else if (c == '*') {
                    res = a * b;
                } else {
                    return null;
                }
                if (res < 0 || res > MAX_VAL) return null;
                stack.push(res);
            }
        }
        if (stack.size() != 1) return null;
        return (long) stack.pop();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int LIMIT = 1024; // values must be in [0, 2^10)
    static String s;
    static int n;

    // memo[l][r][type]:
    // type 0 = expression with +,- precedence handling
    // type 1 = term with * precedence handling
    // type 2 = factor = number or parenthesized expression
    static BitSet[][][] memo;
    static boolean[][][] vis;

    static BitSet emptySet() {
        return new BitSet(LIMIT);
    }

    static BitSet singleton(int x) {
        BitSet bs = new BitSet(LIMIT);
        if (0 <= x && x < LIMIT) bs.set(x);
        return bs;
    }

    static BitSet copy(BitSet b) {
        return (BitSet) b.clone();
    }

    static boolean matchChar(char actual, char need) {
        return actual == '.' || actual == need;
    }

    static boolean matchDigit(char actual) {
        return actual == '.' || actual == '0' || actual == '1';
    }

    static boolean matchOpPM(char actual) {
        return actual == '.' || actual == '+' || actual == '-';
    }

    static boolean matchMul(char actual) {
        return actual == '.' || actual == '*';
    }

    // Parse a binary number on substring [l..r]
    static BitSet parseNumber(int l, int r) {
        if (l > r) return emptySet();
        BitSet cur = singleton(0);
        for (int i = l; i <= r; i++) {
            if (!matchDigit(s.charAt(i))) return emptySet();
            BitSet next = new BitSet(LIMIT);
            boolean can0 = (s.charAt(i) == '.' || s.charAt(i) == '0');
            boolean can1 = (s.charAt(i) == '.' || s.charAt(i) == '1');
            for (int v = cur.nextSetBit(0); v >= 0; v = cur.nextSetBit(v + 1)) {
                if (can0) {
                    int nv = v << 1;
                    if (nv < LIMIT) next.set(nv);
                }
                if (can1) {
                    int nv = (v << 1) | 1;
                    if (nv < LIMIT) next.set(nv);
                }
            }
            cur = next;
            if (cur.isEmpty()) return cur;
        }
        return cur;
    }

    static BitSet combineAddSub(BitSet A, BitSet B, boolean plus) {
        BitSet res = new BitSet(LIMIT);
        for (int a = A.nextSetBit(0); a >= 0; a = A.nextSetBit(a + 1)) {
            if (plus) {
                for (int b = B.nextSetBit(0); b >= 0; b = B.nextSetBit(b + 1)) {
                    int v = a + b;
                    if (v < LIMIT) res.set(v);
                }
            } else {
                for (int b = B.nextSetBit(0); b >= 0; b = B.nextSetBit(b + 1)) {
                    int v = a - b;
                    if (0 <= v && v < LIMIT) res.set(v);
                }
            }
        }
        return res;
    }

    static BitSet combineMul(BitSet A, BitSet B) {
        BitSet res = new BitSet(LIMIT);
        for (int a = A.nextSetBit(0); a >= 0; a = A.nextSetBit(a + 1)) {
            if (a == 0) {
                if (!B.isEmpty()) res.set(0);
                continue;
            }
            for (int b = B.nextSetBit(0); b >= 0; b = B.nextSetBit(b + 1)) {
                long v = 1L * a * b;
                if (v < LIMIT) res.set((int) v);
            }
        }
        return res;
    }

    static BitSet solve(int l, int r, int type) {
        if (l > r) return emptySet();
        if (vis[l][r][type]) return memo[l][r][type];
        vis[l][r][type] = true;
        BitSet res = new BitSet(LIMIT);

        if (type == 2) { // factor
            // number
            res.or(parseNumber(l, r));

            // '(' expression ')'
            if (l + 1 <= r && matchChar(s.charAt(l), '(') && matchChar(s.charAt(r), ')')) {
                res.or(solve(l + 1, r - 1, 0));
            }
        } else if (type == 1) { // term: factor | term * factor
            res.or(solve(l, r, 2)); // single factor

            for (int k = l; k < r; k++) {
                if (matchMul(s.charAt(k))) {
                    BitSet left = solve(l, k - 1, 1);
                    if (left.isEmpty()) continue;
                    BitSet right = solve(k + 1, r, 2);
                    if (right.isEmpty()) continue;
                    res.or(combineMul(left, right));
                }
            }
        } else { // expression: term | expression (+|-) term
            res.or(solve(l, r, 1)); // single term

            for (int k = l; k < r; k++) {
                if (matchOpPM(s.charAt(k))) {
                    BitSet left = solve(l, k - 1, 0);
                    if (left.isEmpty()) continue;
                    BitSet right = solve(k + 1, r, 1);
                    if (right.isEmpty()) continue;

                    char c = s.charAt(k);
                    if (c == '.' || c == '+') {
                        res.or(combineAddSub(left, right, true));
                    }
                    if (c == '.' || c == '-') {
                        res.or(combineAddSub(left, right, false));
                    }
                }
            }
        }

        memo[l][r][type] = res;
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        s = br.readLine();
        n = s.length();

        memo = new BitSet[n][n][3];
        vis = new boolean[n][n][3];

        BitSet ans = solve(0, n - 1, 0);
        if (ans.isEmpty()) {
            System.out.println(-1);
        } else {
            System.out.println(ans.previousSetBit(LIMIT - 1));
        }
    }
}

import sys

def solve():
    expr = sys.stdin.readline().strip()

    # Find positions of '.'
    dots = [i for i, ch in enumerate(expr) if ch == '.']
    n_dots = len(dots)

    # All possible replacement characters
    chars = ['0', '1', '+', '-', '*', '(', ')']

    max_result = -1

    # Generate all combinations recursively
    def dfs(idx, current_expr):
        nonlocal max_result
        if idx == n_dots:
            # Try to evaluate
            res = evaluate(current_expr)
            if res is not None:
                if res > max_result:
                    max_result = res
            return
        pos = dots[idx]
        for ch in chars:
            current_expr[pos] = ch
            dfs(idx + 1, current_expr)
        current_expr[pos] = '.'

    # Convert to list for mutation
    expr_list = list(expr)
    dfs(0, expr_list)

    print(max_result)

# Parser and evaluator
def evaluate(s):
    # Returns integer result or None if invalid
    s = ''.join(s)
    # Check parentheses balance
    if not check_balance(s):
        return None
    # Tokenize and parse
    tokens = tokenize(s)
    if tokens is None:
        return None
    # Parse expression
    parser = Parser(tokens)
    try:
        val = parser.parse_expr()
        if parser.pos != len(tokens):
            return None
        if val is None:
            return None
        if val < 0 or val >= 1024:
            return None
        return val
    except:
        return None

def check_balance(s):
    bal = 0
    for ch in s:
        if ch == '(':
            bal += 1
        elif ch == ')':
            bal -= 1
            if bal < 0:
                return False
    return bal == 0

def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] in '()+-*':
            tokens.append(s[i])
            i += 1
        elif s[i] in '01':
            start = i
            while i < n and s[i] in '01':
                i += 1
            num_str = s[start:i]
            if len(num_str) > 10:  # would exceed 1023
                return None
            num = int(num_str, 2)
            if num >= 1024:
                return None
            tokens.append(('NUM', num))
        else:
            return None
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse_expr(self):
        # <expression> ::= <term> ( ('+' | '-') <term> )*
        left = self.parse_term()
        if left is None:
            return None
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            if right is None:
                return None
            if op == '+':
                left += right
            else:
                left -= right
            if left < 0 or left >= 1024:
                return None
        return left

    def parse_term(self):
        # <term> ::= <factor> ( '*' <factor> )*
        left = self.parse_factor()
        if left is None:
            return None
        while self.peek() == '*':
            self.consume()
            right = self.parse_factor()
            if right is None:
                return None
            left *= right
            if left < 0 or left >= 1024:
                return None
        return left

    def parse_factor(self):
        # <factor> ::= <number> | '(' <expression> ')'
        tok = self.peek()
        if tok is None:
            return None
        if isinstance(tok, tuple) and tok[0] == 'NUM':
            self.consume()
            return tok[1]
        if tok == '(':
            self.consume()
            val = self.parse_expr()
            if val is None:
                return None
            if self.peek() != ')':
                return None
            self.consume()
            return val
        return None

