import itertools

def solve():
    line = input().strip()
    dots = [i for i, c in enumerate(line) if c == '.']
    replacements = '01+-*()'

    max_result = None

    for combo in itertools.product(replacements, repeat=len(dots)):
        expr = list(line)
        for i, c in zip(dots, combo):
            expr[i] = c
        expr = ''.join(expr)

        try:
            result = evaluate(expr)
            if result is not None:
                if max_result is None or result > max_result:
                    max_result = result
        except:
            pass

    if max_result is None:
        print(-1)
    else:
        print(max_result)

def evaluate(expr):
    pos = [0]

    def parse_expr():
        left = parse_term()
        while pos[0] < len(expr) and expr[pos[0]] in '+-':
            op = expr[pos[0]]
            pos[0] += 1
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
            if left < 0 or left >= 1024:
                raise ValueError("out of range")
        return left

    def parse_term():
        left = parse_factor()
        while pos[0] < len(expr) and expr[pos[0]] == '*':
            pos[0] += 1
            right = parse_factor()
            left = left * right
            if left < 0 or left >= 1024:
                raise ValueError("out of range")
        return left

    def parse_factor():
        if pos[0] >= len(expr):
            raise ValueError("unexpected end")
        if expr[pos[0]] == '(':
            pos[0] += 1  # consume '('
            left = parse_term_inner()
            if pos[0] >= len(expr) or expr[pos[0]] != ')':
                raise ValueError("missing )")
            pos[0] += 1
            return left
        else:
            return parse_number()

    def parse_term_inner():
        # inside parens: parse full expression
        left = parse_term()
        while pos[0] < len(expr) and expr[pos[0]] in '+-':
            op = expr[pos[0]]
            pos[0] += 1
            right = parse_term()
            left = left + right if op == '+' else left - right
            if left < 0 or left >= 1024:
                raise ValueError("out of range")
        return left

    def parse_number():
        if pos[0] >= len(expr) or expr[pos[0]] not in '01':
            raise ValueError("expected digit")
        num_str = ''
        while pos[0] < len(expr) and expr[pos[0]] in '01':
            num_str += expr[pos[0]]
            pos[0] += 1
        val = int(num_str, 2)
        if val >= 1024:
            raise ValueError("number out of range")
        return val

    result = parse_expr()
    if pos[0] != len(expr):
        raise ValueError("trailing chars")
    return result

