import sys
from collections import defaultdict

s = sys.stdin.readline().strip()
n = len(s)

LIMIT = 1 << 10  # values must be in [0, 1024)

digits = {'0', '1'}
ops = {'+', '-', '*'}

# dp_num[l][r] = set of possible numeric values represented by substring s[l:r]
dp_num = [[set() for _ in range(n + 1)] for _ in range(n + 1)]

# expr maps:
# add[l][r]: possible values of expressions on s[l:r] with no top-level + or -
#            i.e. product chains / atoms
# expr[l][r]: possible values of full expressions on s[l:r]
add = [[set() for _ in range(n + 1)] for _ in range(n + 1)]
expr = [[set() for _ in range(n + 1)] for _ in range(n + 1)]

# possible operators for a character
def possible_ops(ch):
    if ch == '.':
        return ops
    return {ch} if ch in ops else set()

def can_be(ch, target):
    return ch == target or ch == '.'

# numbers
for l in range(n):
    possible = {0}
    for r in range(l + 1, n + 1):
        ch = s[r - 1]
        nxt = set()
        for v in possible:
            if can_be(ch, '0'):
                nv = v * 2
                if nv < LIMIT:
                    nxt.add(nv)
            if can_be(ch, '1'):
                nv = v * 2 + 1
                if nv < LIMIT:
                    nxt.add(nv)
        if not nxt:
            break
        dp_num[l][r] = nxt
        possible = nxt

for length in range(1, n + 1):
    for l in range(n - length + 1):
        r = l + length

        # atom: number
        if dp_num[l][r]:
            add[l][r].update(dp_num[l][r])

        # atom: parenthesized full expression "(expr op expr)"
        if length >= 5 and can_be(s[l], '(') and can_be(s[r - 1], ')'):
            inner_l, inner_r = l + 1, r - 1
            # split inner into expr op expr, where op is top-level inside parentheses
            for k in range(inner_l + 1, inner_r):
                for op in possible_ops(s[k]):
                    left = expr[inner_l][k]
                    right = expr[k + 1][inner_r]
                    if not left or not right:
                        continue
                    if op == '+':
                        for a in left:
                            for b in right:
                                c = a + b
                                if c < LIMIT:
                                    add[l][r].add(c)
                    elif op == '-':
                        for a in left:
                            for b in right:
                                c = a - b
                                if 0 <= c < LIMIT:
                                    add[l][r].add(c)
                    else:  # '*'
                        for a in left:
                            if a == 0:
                                add[l][r].add(0)
                                continue
                            for b in right:
                                c = a * b
                                if c < LIMIT:
                                    add[l][r].add(c)

        # multiplication chain: add * add, left associative but since all factors are already
        # in add-form (no top-level + or -), splitting at any top-level * is sufficient
        for k in range(l + 1, r - 1):
            if '*' not in possible_ops(s[k]):
                continue
            left = add[l][k]
            right = add[k + 1][r]
            if not left or not right:
                continue
            for a in left:
                if a == 0:
                    add[l][r].add(0)
                    continue
                for b in right:
                    c = a * b
                    if c < LIMIT:
                        add[l][r].add(c)

        # full expression can be add-form
        if add[l][r]:
            expr[l][r].update(add[l][r])

        # addition/subtraction, left-to-right after multiplications
        # This is captured by splitting expr op add
        for k in range(l + 1, r - 1):
            poss = possible_ops(s[k])
            if not poss:
                continue
            left = expr[l][k]
            right = add[k + 1][r]
            if not left or not right:
                continue
            if '+' in poss:
                for a in left:
                    for b in right:
                        c = a + b
                        if c < LIMIT:
                            expr[l][r].add(c)
            if '-' in poss:
                for a in left:
                    for b in right:
                        c = a - b
                        if 0 <= c < LIMIT:
                            expr[l][r].add(c)

